#!/usr/bin/env bash
# Question 15: Pods of ${Q15_APP} keep restarting. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q15_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q15_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q15_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q15_APP}
  namespace: ${Q15_NS}
  labels: { app: ${Q15_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q15_APP} }
  template:
    metadata:
      labels: { app: ${Q15_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
            limits: { cpu: 250m, memory: 128Mi }
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          livenessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
            failureThreshold: 2
EOF
kubectl -n "${Q15_NS}" get deployment "${Q15_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q15.uid"
chmod 644 "/var/tmp/cka-q15.uid"

case "${Q15_FAULT}" in
  liveness-port)
    kubectl -n "${Q15_NS}" patch deployment "${Q15_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","livenessProbe":{"httpGet":{"path":"/","port":8080}}}]}}}}'
    ;;
  liveness-path)
    kubectl -n "${Q15_NS}" patch deployment "${Q15_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","livenessProbe":{"httpGet":{"path":"/healthz","port":80}}}]}}}}'
    ;;
  liveness-exec)
    kubectl -n "${Q15_NS}" patch deployment "${Q15_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/livenessProbe","value":{"exec":{"command":["cat","/tmp/healthy"]},"periodSeconds":5,"failureThreshold":2}}]'
    ;;
  liveness-early)
    kubectl -n "${Q15_NS}" patch deployment "${Q15_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["/bin/sh","-c","sleep 20; exec nginx -g \"daemon off;\""],"livenessProbe":{"httpGet":{"path":"/","port":80},"initialDelaySeconds":2,"periodSeconds":3,"failureThreshold":2}}]}}}}'
    ;;
  nginx-config-error)
    printf '%s\n' 'server {' '    listen 80' '    location / {' '        root /usr/share/nginx/html;' '        index index.html;' '    }' '}' > "/var/tmp/cka-q15.default.conf"
    kubectl -n "${Q15_NS}" create configmap "${Q15_APP}-nginx" --from-file=default.conf="/var/tmp/cka-q15.default.conf" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
    kubectl -n "${Q15_NS}" patch deployment "${Q15_APP}" -p '{"spec":{"template":{"spec":{"volumes":[{"name":"nginx-conf","configMap":{"name":"'"${Q15_APP}"'-nginx"}}],"containers":[{"name":"web","volumeMounts":[{"name":"nginx-conf","mountPath":"/etc/nginx/conf.d"}]}]}}}}'
    ;;
  oom-limit)
    kubectl -n "${Q15_NS}" set resources "deployment/${Q15_APP}" -c web --requests=memory=4Mi --limits=memory=4Mi
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q15_NS}" scale "deployment/${Q15_APP}" --replicas=2
# What the learner must keep: the command and arguments as they are now, broken run or not.
kubectl -n "${Q15_NS}" get deployment "${Q15_APP}" -o jsonpath='{.spec.template.spec.containers[0].command}|{.spec.template.spec.containers[0].args}' > "/var/tmp/cka-q15.cmd"
chmod 644 "/var/tmp/cka-q15.cmd"
for _ in $(seq 1 60); do
  [[ "$(kubectl -n "${Q15_NS}" get pods -l "app=${Q15_APP}" -o jsonpath='{range .items[*]}{.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null | awk '{s+=$1} END {print s+0}')" -ge 1 ]] && exit 0
  sleep 3
done
echo "the Pods of ${Q15_APP} do not restart" >&2
exit 1
